variable.!post_object_hook:
from requests import post
from requests.packages import urllib3
from time import sleep
urllib3.disable_warnings()
from func.json import json_decode
proxy = {'http': ${proxy} if ${proxy} not in ['', 'None', 'null'] else None, 'https': ${proxy} if ${proxy} not in ['', 'None', 'null'] else None}
header = {'User-Agent': @{ua}}
err_count = 0
while True:
 try:
  response = post(!{get_post_api_by_id}, proxies = proxy, headers = header, verify = False)
  res = json_decode(response.text, True)
  if 'id' in res:
   ${post_object}.update({'hook_add': res})
   print('zerochan.advanced.variable.!post_object_hook: [' + str(${index} + 1) + ']获取' + str(#{id}) + '信息成功')
   break
 except Exception as e:
  err_count += 1
  if err_count > ${retry_max} and ${retry_max} != -1:
   print('zerochan.advanced.variable.!post_object_hook: [' + str(${index} + 1) + ']获取' + str(#{id}) + '信息时出现错误, 超过最大重试次数')
   break
  else:
   print('zerochan.advanced.variable.!post_object_hook: [' + str(${index} + 1) + ']获取' + str(#{id}) + '信息时出现错误, 即将第' + str(err_count) + '次重试')
   sleep(err_count * 10)
exec_result = ${post_object}
